&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de magus&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_magus_0&quot; href=&quot;#Les_arch&#233;types_de_magus_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Occulte-(Magus).html&quot; title=&quot;Archer occulte&quot;&gt;Archer occulte&lt;/a&gt; (HOTS)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;l&#233;mentaire-(Magus).html&quot; title=&quot;Chevalier &#233;l&#233;mentaire (magus)&quot;&gt;Chevalier &#233;l&#233;mentaire&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Suli-(Race).html&quot; title=&quot;Les sulis&quot;&gt;Suli&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danse-Sort-(Magus).html&quot; title=&quot;Danse-sort&quot;&gt;Danse-sort&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-De-La-Tour-(Magus).html&quot; title=&quot;D&#233;fenseur de la tour&quot;&gt;D&#233;fenseur de la tour&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;corcheur-Fi&#233;lon-(Magus).html&quot; title=&quot;&#201;corcheur fi&#233;lon&quot;&gt;&#201;corcheur fi&#233;lon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;sot&#233;riste-(Magus).html&quot; title=&quot;&#201;sot&#233;riste&quot;&gt;&#201;sot&#233;riste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forge&#226;me-(Magus).html&quot; title=&quot;Forge&#226;me&quot;&gt;Forge&#226;me&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kensai-(Magus).html&quot; title=&quot;Kensai&quot;&gt;Kensai&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lameli&#233;-(Magus).html&quot; title=&quot;Lameli&#233;&quot;&gt;Lameli&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesprit-(Magus).html&quot; title=&quot;Lamesprit&quot;&gt;Lamesprit&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesort-(Magus).html&quot; title=&quot;Lamesort&quot;&gt;Lamesort&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-De-Mal&#233;fices-(Magus).html&quot; title=&quot;Lanceur de mal&#233;fices&quot;&gt;Lanceur de mal&#233;fices&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mage-De-Bataille-Blind&#233;-(Magus).html&quot; title=&quot;Mage de bataille blind&#233;&quot;&gt;Mage de bataille blind&#233;&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myrmidarque-(Magus).html&quot; title=&quot;Myrmidarque&quot;&gt;Myrmidarque&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejeton-&#201;trange-(Magus).html&quot; title=&quot;Rejeton &#233;trange&quot;&gt;Rejeton &#233;trange&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Skirnir-(Magus).html&quot; title=&quot;Skirnir&quot;&gt;Skirnir&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialiste-Du-B&#226;ton-(Magus).html&quot; title=&quot;Sp&#233;cialiste du b&#226;ton&quot;&gt;Sp&#233;cialiste du b&#226;ton&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Tieffelin.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Tieffelin (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Tieffelin.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;tieffelins&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Certains magi tieffelins peuvent puiser l’&#233;nergie sombre de leur sang fi&#233;lon pour am&#233;liorer leurs talents magiques et martiaux. En tailladant physiquement leur chair corrompue, ils peuvent utiliser ces sombres &#233;nergies pour renforcer leurs pouvoirs, mat&#233;rialiser des armes &#224; partir de rien et contourner les plus solides d&#233;fenses de leurs ennemis.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mortification infernale (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Mortification_infernale_Sur_0&quot; href=&quot;#Mortification_infernale_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, l’&#233;corcheur fi&#233;lon peut sacrifier une partie de son propre sang infernal pour augmenter sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt;. Sacrifier son sang de cette mani&#232;re lui co&#251;te une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;. Par tranche de 2 points d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissement temporaire&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; qu’il re&#231;oit de cette mani&#232;re, sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt; augmente de 1 point. Tous les points de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt; ainsi gagn&#233;s et non d&#233;pens&#233;s disparaissent la prochaine fois que le magus pr&#233;parera ses sorts. Contrairement aux affaiblissements temporaires normaux de caract&#233;ristiques, ces d&#233;g&#226;ts ne peuvent pas &#234;tre soign&#233;s au moyen d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Partielle.html&quot; title=&quot;Restauration partielle&quot;&gt;restauration partielle&lt;/a&gt;&lt;/i&gt;. Seul le temps gu&#233;rit les d&#233;g&#226;ts de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; re&#231;us d’une mortification infernale. L’&#233;corcheur fi&#233;lon ne peut pas utiliser cette capacit&#233; si ses d&#233;g&#226;ts de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; sont &#233;gaux ou sup&#233;rieurs &#224; la moiti&#233; de son score de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Arcanes du magus&lt;a class=&quot;headeranchor&quot; id=&quot;Arcanes_du_magus_1&quot; href=&quot;#Arcanes_du_magus_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’&#233;corcheur fi&#233;lon a acc&#232;s aux arcanes de magus suivants. Il ne peut en prendre aucun plus d’une fois. 
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Frappe de contournement (Sur).&lt;/i&gt; L’&#233;corcheur fi&#233;lon peut d&#233;penser 1 point de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; pour permettre &#224; une attaque de corps &#224; corps ou une &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#FRAPPEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;frappe magique&lt;/a&gt;] qu’il a faite avant la fin de son tour d’ignorer la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;r&#233;duction de d&#233;g&#226;ts&lt;/a&gt; d’un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;ext&#233;rieur&lt;/a&gt; Mauvais.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Lame fi&#233;lone (Sur).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, et tant qu’il a utilis&#233; mortification infernale ce jour-l&#224; pour augmenter sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt;, l’&#233;corcheur fi&#233;lon peut faire appara&#238;tre une arme avec cet arcane. Il lui en co&#251;te 2 points de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt;. L’arme peut prendre la forme de n’importe quelle arme de corps &#224; corps &#224; une main que l’&#233;corcheur fi&#233;lon sait manier. Cette arme commence avec un bonus d’alt&#233;ration de +1, mais tous les quatre niveaux apr&#232;s le 3e, l’arme gagne un nouveau bonus d’alt&#233;ration de +1, jusqu’&#224; un maximum de +5 au niveau 19. Cette arme invoqu&#233;e dure 1 minute. Au niveau 5, ces bonus peuvent &#234;tre utilis&#233;s pour ajouter n’importe laquelle des propri&#233;t&#233;s suivantes &#224; la lame fi&#233;lone : &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Ac&#233;r&#233;e.html&quot; title=&quot;ac&#233;r&#233;e (propri&#233;t&#233;)&quot;&gt;ac&#233;r&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Anarchique.html&quot; title=&quot;anarchique (propri&#233;t&#233;)&quot;&gt;anarchique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Axiomatique.html&quot; title=&quot;axiomatique (propri&#233;t&#233;)&quot;&gt;axiomatique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Dansante.html&quot; title=&quot;dansante (propri&#233;t&#233;)&quot;&gt;dansante&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;feu&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu-Intense.html&quot; title=&quot;feu intense (propri&#233;t&#233;)&quot;&gt;feu intense&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Froid.html&quot; title=&quot;froid (propri&#233;t&#233;)&quot;&gt;froid&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Froid-Intense.html&quot; title=&quot;froid intense (propri&#233;t&#233;)&quot;&gt;froid intense&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Foudre.html&quot; title=&quot;foudre (propri&#233;t&#233;)&quot;&gt;foudre&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Foudre-Intense.html&quot; title=&quot;foudre intense (propri&#233;t&#233;)&quot;&gt;foudre intense&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Impie.html&quot; title=&quot;impie (propri&#233;t&#233;)&quot;&gt;impie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Rapide.html&quot; title=&quot;rapide (propri&#233;t&#233;)&quot;&gt;rapide&lt;/a&gt;. Ces bonus et propri&#233;t&#233;s sont d&#233;finis lorsque sont d&#233;pens&#233;s les points de la r&#233;serve magique, et ne peuvent plus &#234;tre chang&#233;s jusqu’&#224; la prochaine fois que l’&#233;corcheur fi&#233;lon utilise cet arcane. La lame fi&#233;lone ne peut pas &#234;tre mani&#233;e par une autre cr&#233;ature ; si elle quitte la main de l’&#233;corcheur fi&#233;lon, elle se dissipe en volutes de fum&#233;e rouge sentant le sang br&#251;l&#233;. L’&#233;corcheur fi&#233;lon ne peut faire appara&#238;tre qu’une seule lame fi&#233;lone &#224; la fois. S’il utilise &#224; nouveau sa capacit&#233;, la premi&#232;re lame fi&#233;lone dispara&#238;t.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
